import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = process.env.NOVA_TEST_KEY || '';
const BASE = (process.env.NOVA_TEST_BASE || 'https://www.aioss.cc').replace(/\/+$/, '');
const MODEL = process.env.NOVA_TEST_MODEL || 'gpt-image-2.5-flare';
const SIZE_ENV = process.env.NOVA_TEST_SIZE ?? '3840x2160';
const SIZE = SIZE_ENV === 'auto' || SIZE_ENV === '' ? null : SIZE_ENV; // 'auto' omits size, like the app
const STREAM = process.env.NOVA_TEST_STREAM !== '0';
const FORMAT = process.env.NOVA_TEST_FORMAT || 'png'; // the app always sends png today
const COMPRESSION = process.env.NOVA_TEST_COMPRESSION ? Number(process.env.NOVA_TEST_COMPRESSION) : undefined;
const OUT = path.join(process.env.TEMP || '.', 'nova-ui-bench', 'image-api-test');
const PROMPT = 'A farmer bending over to harvest ripe wheat in a golden field, warm evening light';
const mask = (s) => (KEY ? String(s ?? '').split(KEY).join('sk-***') : String(s ?? ''));
const log = (...a) => console.log(mask(a.map((x) => (typeof x === 'string' ? x : JSON.stringify(x))).join(' ')));
const t0 = Date.now();
const at = (t = Date.now()) => `${((t - t0) / 1000).toFixed(1)}s`;
const mb = (n) => `${(n / 1024 / 1024).toFixed(2)} MB`;

function parseJsonSafely(t) {
  try { return JSON.parse(t); } catch { return null; }
}

// Same SSE framing as backend/server.js parseImageEventStream.
function parseSse(t) {
  const out = [];
  let lines = [];
  const flush = () => {
    if (!lines.length) return;
    const raw = lines.join('\n').trim();
    lines = [];
    if (raw && raw !== '[DONE]') {
      const parsed = parseJsonSafely(raw);
      if (parsed) out.push(parsed);
    }
  };
  for (const rawLine of String(t).split(/\r?\n/)) {
    const line = rawLine.trimEnd();
    if (line === '') { flush(); continue; }
    if (line.startsWith(':')) continue;
    if (line.startsWith('data:')) lines.push(line.slice(5).trimStart());
  }
  flush();
  return out;
}

// Same lookup as backend/server.js getImagePayloadValue; only string values are usable.
function pickImage(d, depth = 0) {
  if (!d || depth > 3 || typeof d !== 'object') return undefined;
  if (Array.isArray(d)) {
    for (const x of d) { const v = pickImage(x, depth + 1); if (v) return v; }
    return undefined;
  }
  const first = Array.isArray(d.data) ? d.data.find((x) => x && typeof x === 'object' && (x.b64_json || x.url || x.image_url)) : undefined;
  const v = first?.b64_json || first?.url || first?.image_url || d.b64_json || d.url || d.image_url;
  if (v) return typeof v === 'string' ? v : undefined;
  return pickImage(d.result, depth + 1) || pickImage(d.response, depth + 1) || pickImage(d.output, depth + 1);
}

// Real format and dimensions from the file header (PNG, WebP, JPEG).
function imageInfo(buf) {
  if (buf.length > 24 && buf.subarray(1, 4).toString() === 'PNG') {
    return { type: 'png', ext: 'png', dims: `${buf.readUInt32BE(16)}x${buf.readUInt32BE(20)}` };
  }
  if (buf.length > 30 && buf.subarray(0, 4).toString() === 'RIFF' && buf.subarray(8, 12).toString() === 'WEBP') {
    const chunk = buf.subarray(12, 16).toString();
    let dims = '?';
    if (chunk === 'VP8X') dims = `${1 + buf.readUIntLE(24, 3)}x${1 + buf.readUIntLE(27, 3)}`;
    else if (chunk === 'VP8 ') dims = `${buf.readUInt16LE(26) & 0x3fff}x${buf.readUInt16LE(28) & 0x3fff}`;
    else if (chunk === 'VP8L') { const b = buf.readUInt32LE(21); dims = `${(b & 0x3fff) + 1}x${((b >>> 14) & 0x3fff) + 1}`; }
    return { type: 'webp', ext: 'webp', dims };
  }
  if (buf[0] === 0xff && buf[1] === 0xd8) {
    let i = 2;
    while (i + 9 < buf.length && buf[i] === 0xff) {
      const marker = buf[i + 1];
      if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker)) {
        return { type: 'jpeg', ext: 'jpg', dims: `${buf.readUInt16BE(i + 7)}x${buf.readUInt16BE(i + 5)}` };
      }
      i += 2 + buf.readUInt16BE(i + 2);
    }
    return { type: 'jpeg', ext: 'jpg', dims: '?' };
  }
  return { type: `unknown(${buf.subarray(0, 8).toString('hex')})`, ext: 'bin', dims: '?' };
}

const shape = (v) => (typeof v === 'string'
  ? (v.length > 120 ? `<str ${v.length}>` : v)
  : Array.isArray(v) ? v.slice(0, 4).map(shape)
    : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, k === 'usage' ? '{…}' : shape(x)])) : v);

async function probeBandwidth() {
  const home = await fetch(`${BASE}/`, { headers: { 'accept-encoding': 'identity' }, signal: AbortSignal.timeout(30000) });
  const html = await home.text();
  const assets = [...new Set([...html.matchAll(/(?:src|href)="([^"]+\.(?:js|css))"/g)].map((m) => new URL(m[1], `${BASE}/`).href))];
  let bytes = 0;
  const start = Date.now();
  for (const url of assets.slice(0, 8)) {
    const r = await fetch(url, { headers: { 'accept-encoding': 'identity' }, signal: AbortSignal.timeout(90000) });
    bytes += Buffer.from(await r.arrayBuffer()).length;
  }
  const secs = Math.max(0.001, (Date.now() - start) / 1000);
  log(`bandwidth: ${mb(bytes)} in ${secs.toFixed(1)} s = ${(bytes / 1024 / secs).toFixed(0)} KB/s (home ${home.status}, ${assets.length} assets)`);
}

async function listModels() {
  const r = await fetch(`${BASE}/v1/models`, { headers: { Authorization: `Bearer ${KEY}` }, signal: AbortSignal.timeout(20000) });
  const d = parseJsonSafely(await r.text());
  const ids = Array.isArray(d?.data) ? d.data.map((m) => m?.id).filter(Boolean) : [];
  log(`models ${r.status}: ${ids.join(', ') || '(none)'}`);
}

async function instrumentedGenerate() {
  const body = {
    prompt: PROMPT,
    model: MODEL,
    ...(STREAM ? { stream: true } : {}),
    ...(SIZE ? { size: SIZE } : {}),
    quality: 'auto',
    background: 'auto',
    output_format: FORMAT,
    ...(COMPRESSION !== undefined ? { output_compression: COMPRESSION } : {}),
  };
  log(`POST ${BASE}/v1/images/generations body=${JSON.stringify({ ...body, prompt: '<prompt>' })}`);
  const res = await fetch(`${BASE}/v1/images/generations`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${KEY}` },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(15 * 60 * 1000),
  });
  const headersAt = Date.now();
  const contentType = String(res.headers.get('content-type') || '').toLowerCase();
  log(`[${at(headersAt)}] headers ${res.status} content-type=${contentType || '-'} content-length=${res.headers.get('content-length') || '-'} server=${res.headers.get('server') || '-'}`);
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let text = '';
  let bytes = 0;
  let firstByteAt = null;
  let lastChunkAt = headersAt;
  let windowBytes = 0;
  let windowStart = headersAt;
  const gaps = [];
  for (;;) {
    const { done, value } = await reader.read();
    const now = Date.now();
    if (done) break;
    if (firstByteAt === null) {
      firstByteAt = now;
      log(`[${at(now)}] first body bytes`);
    }
    if (now - lastChunkAt > 3000) gaps.push(`${((now - lastChunkAt) / 1000).toFixed(1)}s idle at ${mb(bytes)}`);
    lastChunkAt = now;
    bytes += value.length;
    windowBytes += value.length;
    text += decoder.decode(value, { stream: true });
    if (now - windowStart >= 10000) {
      const secs = (now - windowStart) / 1000;
      log(`[${at(now)}] +${(windowBytes / 1024).toFixed(0)} KB in ${secs.toFixed(0)} s = ${(windowBytes / 1024 / secs).toFixed(0)} KB/s, total ${mb(bytes)}`);
      windowBytes = 0;
      windowStart = now;
    }
  }
  const endAt = Date.now();
  log(`[${at(endAt)}] response complete, ${mb(bytes)} total`);
  if (gaps.length) log('idle gaps > 3 s:', gaps.slice(0, 10));

  // What the app would do with this response (backend/server.js parseGptImageResponse).
  const looksSse = /^\s*(data:|event:|:)/.test(text);
  const events = looksSse ? parseSse(text) : [];
  if (looksSse) {
    const counts = {};
    for (const e of events) counts[e?.type || '(no type)'] = (counts[e?.type || '(no type)'] || 0) + 1;
    log('SSE events:', counts);
  }
  let verdict;
  let imageValue;
  if (!res.ok) {
    verdict = `app: FAIL, HTTP ${res.status} ${text.slice(0, 200)}`;
  } else if (contentType.includes('text/event-stream')) {
    const hit = [...events].reverse().find((e) => !String(e?.type || '').toLowerCase().includes('partial') && pickImage(e));
    if (hit) {
      log('image event:', shape(hit));
      imageValue = pickImage(hit);
      verdict = `app: OK (event "${hit.type || '(no type)'}"), no retry`;
    } else {
      if (events.length) log('last event:', shape(events.at(-1)));
      verdict = 'app: FAIL "响应中无图片数据" -> non-stream retry = a second generation';
    }
  } else {
    const data = parseJsonSafely(text);
    if (!data) {
      verdict = `app: FAIL "响应 JSON 格式无效" (content-type ${contentType || 'missing'}) -> non-stream retry = a second generation`;
    } else {
      log('JSON body:', shape(data));
      imageValue = pickImage(data);
      verdict = imageValue ? 'app: OK (JSON body), no retry' : 'app: FAIL "响应中无图片数据" -> non-stream retry = a second generation';
    }
  }

  let delivery = '-';
  if (imageValue && /^https?:\/\//i.test(imageValue)) {
    const d0 = Date.now();
    try {
      const r = await fetch(imageValue, { signal: AbortSignal.timeout(5 * 60 * 1000) });
      const buf = Buffer.from(await r.arrayBuffer());
      const info = imageInfo(buf);
      const secs = (Date.now() - d0) / 1000;
      delivery = `URL (${new URL(imageValue).host})`;
      log(`image is a URL -> the app downloads it: ${r.status} ${info.type} ${info.dims} ${mb(buf.length)} in ${secs.toFixed(1)} s (${(buf.length / 1024 / Math.max(0.001, secs)).toFixed(0)} KB/s) from ${new URL(imageValue).host}`);
    } catch (error) {
      log(`image URL download failed after ${((Date.now() - d0) / 1000).toFixed(1)} s:`, error?.name, error?.message);
    }
  } else if (imageValue) {
    const buf = Buffer.from(imageValue.startsWith('data:') ? imageValue.split(',')[1] : imageValue, 'base64');
    const info = imageInfo(buf);
    await fs.mkdir(OUT, { recursive: true });
    const file = path.join(OUT, `probe-${MODEL}-${SIZE || 'auto'}-${FORMAT}.${info.ext}`);
    await fs.writeFile(file, buf);
    delivery = 'inline base64';
    log(`image is inline base64: ${info.type} ${info.dims} ${mb(buf.length)} (base64 ${mb(imageValue.length)}) -> ${file}`);
  }
  log(verdict);

  const span = (a, b) => (a && b ? `${((b - a) / 1000).toFixed(1)} s` : '-');
  const bodySecs = firstByteAt ? (endAt - firstByteAt) / 1000 : 0;
  log('\nTIMELINE');
  log(`  request -> headers (generation):  ${span(t0, headersAt)}`);
  log(`  headers -> first body bytes:      ${span(headersAt, firstByteAt)}`);
  log(`  body transfer:                    ${span(firstByteAt, endAt)} for ${mb(bytes)} (${bodySecs ? (bytes / 1024 / bodySecs).toFixed(0) : '-'} KB/s)`);
  log(`  total:                            ${span(t0, endAt)}`);
  log(`  delivery:                         ${delivery}`);
}

const phase = process.argv[2] || 'bw';
try {
  if (phase === 'bw') await probeBandwidth();
  else if (phase === 'models') await listModels();
  else if (phase === 'gen') {
    if (!KEY) throw new Error('NOVA_TEST_KEY missing');
    await instrumentedGenerate();
  }
} catch (error) {
  log(`[${at()}] FAILED:`, error?.name, error?.message, error?.cause?.code || '');
